import{_ as c,l as d,o as a,c as n,v as o,p as i,x as t,d as l,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"异常与中断入口","description":"","frontmatter":{"title":"异常与中断入口","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/exception-interrupt-entry.md","filePath":"cs/exception-interrupt-entry.md","lastUpdated":1789023840000}'),E={name:"cs/exception-interrupt-entry.md"};function h(m,e,u,A,C,_){const r=d("Mermaid");return a(),n("div",null,[e[1]||(e[1]=o('<h1 id="异常与中断入口" tabindex="-1">异常与中断入口 <a class="header-anchor" href="#异常与中断入口" aria-label="Permalink to &quot;异常与中断入口&quot;">​</a></h1><div class="epigraph"><p>指令内部的故障与外部的异步请求都不能当成 `jal`：要保存当时的 PC 与原因，再跳到事先约定的入口。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；The RISC-V Instruction Set Manual, Volume II: Privileged Architecture 整理</footer></div><p>上一课<a href="/cs/calling-convention-stack">调用约定与栈</a>钉死了自愿的 <code>jal</code> 与栈帧。本课不重画 ABI 寄存器表，也不从操作系统下半部另起。缺口是：未对齐的 <code>lw</code>、非法 opcode、外部设备请求，都要打断顺序执行。它们<strong>不是过程调用</strong>：没有编译器安排的 <code>ra</code>，必须由硬件写入专门的 CSR，并把 PC 改到入口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单周期/多周期到现在只处理正常指令。缺口是陷阱路径：同步异常（相对某条指令）与异步中断（相对时钟边沿）。硬件：停止当前指令的提交（或定义哪一条被杀死），把 PC 写入 <code>mepc</code>（教学用机器模式名），原因写入 <code>mcause</code>，PC ← <code>mtvec</code>（基址或向量）。返回用 <code>mret</code> 恢复 PC，不是 <code>jalr ra</code>。</p><p>本课只钉入口与保存。谁允许接受中断、用户态能否执行 <code>mret</code>，是<a href="/cs/privilege-rings">下一课</a>的特权级。</p><h3 id="中断不是「再来一条分支指令」" tabindex="-1">中断不是「再来一条分支指令」 <a class="header-anchor" href="#中断不是「再来一条分支指令」" aria-label="Permalink to &quot;中断不是「再来一条分支指令」&quot;">​</a></h3><p>分支是指令语义内的 PC 更新。中断可以在指令之间插入，不对应程序里的 <code>beq</code>。把中断服务写成普通函数却不保存 <code>mepc</code>，返回会跳错。入口处的寄存器保存是软件的第二套「调用约定」（往往更完整），与 ABI 的 caller-saved 不是同一张表。</p><p><span class="marginnote">Patterson/Hennessy 用异常说明控制流的第三种（顺序、分支、陷阱）。RISC-V 特权手册定义 <code>mtvec</code>/<code>mepc</code>/<code>mcause</code>。教材若只用「异常 PC 寄存器」不写 CSR 名，对象仍是同一组。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分类：故障（需指向过错指令以便重试或 kill）、陷阱（ecall，指向后一条）、中断（指向未执行的下一条）。精确异常：对外可见状态像是停在那条边界上。多周期在确定拍转入「保存并跳转」状态；单周期要加异常 MUX 改 PC，并抑制写堆/写存。</p>',11)),(a(),i(p,null,{default:t(()=>[s(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20EVT%5B%22%E5%BC%82%E5%B8%B8%E6%88%96%E4%B8%AD%E6%96%AD%22%5D%20--%3E%20SAVE%5B%22%E4%BF%9D%E5%AD%98%20PC%20%E4%B8%8E%20cause%22%5D%0A%20%20SAVE%20--%3E%20VEC%5B%22PC%20%E2%86%90%20%E5%85%A5%E5%8F%A3%22%5D%0A%20%20VEC%20--%3E%20HND%5B%22%E8%BD%AF%E4%BB%B6%E4%BF%9D%E5%AD%98%E9%80%9A%E7%94%A8%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20HND%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%85%A5%E5%8F%A3%E4%B8%BA%E4%BD%95%E5%9C%A8%E6%9B%B4%E9%AB%98%E7%89%B9%E6%9D%83%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p><code>ecall</code> 是自愿陷入，用来请求后课才会讲的系统服务；本课只当同步陷阱。中断需在状态机里采样、可能等当前指令完成以保证精确。流水线上的异常更麻烦，体系结构课再开。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 Linux 信号、不讲底半部软中断。不把 DMA 完成当成与中断同一机制以外的魔法：它通常以中断通知。页故障的处理要有页表，很后。</p><p>后课默认：非指令内控制流走陷阱入口，PC 与原因在 CSR 里。入口代码跑在更高特权，下一课钉级。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>异常/中断保存 PC 与原因，跳到 <code>mtvec</code>，用 <code>mret</code> 返回。</li><li>与 <code>jal</code> 的栈约定分离；精确性要求定义停在哪条指令。</li><li>特权尚未分级，但入口已经需要「能执行 <code>mret</code> 的模式」。</li><li>出处：Patterson and Hennessy, COD (RISC-V)；RISC-V Privileged Spec。</li></ul>',7))])}const D=c(E,[["render",h]]);export{P as __pageData,D as default};
